0%




                        MULAI SESI 1: Wajah Datar



Menunggu perintah...





                Kembali ke Kelola User







    // --- UPDATE SCRIPT YANG LEBIH STABIL ---

    // Pakai tanda kutip agar aman
    let userId = parseInt("{{ user_id }}");

    let totalFoto = 0; // Urutan file (akan direset kalau sesi baru, atau lanjut terserah logika)
    // Kita buat logic agar totalFoto melanjutkan file yang ada di folder nanti
    // Tapi untuk simpelnya di sesi web, kita hitung global 1-80

    let countSesi = 0; // Target 20 per sesi

    // Daftar Instruksi
    const sesiList = [
        { id: 1, text: "Sesi 1: WAJAH DATAR", btnNext: "MULAI" },
        { id: 2, text: "Sesi 2: WAJAH SENYUM", btnNext: "MULAI" },
        { id: 3, text: "Sesi 3: WAJAH SERONG KIRI", btnNext: "MULAI" },
        { id: 4, text: "Sesi 4: WAJAH SERONG KANAN", btnNext: "MULAI" }
    ];

    function mulaiSesi(nomorSesi) {
        let config = sesiList[nomorSesi - 1];
        document.getElementById("instruksi").innerText = "MEREKAM: " + config.text;

        // Matikan tombol biar gak diklik dobel
        document.getElementById("btn-container").innerHTML = 'Sedang Merekam...';

        countSesi = 0;

        // --- PERUBAHAN UTAMA: PANGGIL FUNGSI REKURSIF ---
        ambilSatuFoto(nomorSesi); 
    }

    function ambilSatuFoto(nomorSesi) {
        // Cek Stop Condition
        if (countSesi >= 20) {
            siapkanSesiBerikutnya(nomorSesi);
            return;
        }

        totalFoto++; // Naikkan counter global

        fetch('/api/simpan_frame', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ user_id: userId, urutan: totalFoto })
        })
        .then(response => response.json())
        .then(data => {
            if(data.status === 'success') {
                countSesi++; // Hitung sukses
                updateProgress();
                document.getElementById("status").innerText = "Foto tersimpan: " + countSesi + "/20 (Total: " + totalFoto + ")";

                // --- REKURSIF: Panggil diri sendiri SETELAH sukses ---
                // Kasih jeda dikit 200ms biar user sempat gerak/napas
                setTimeout(() => {
                    ambilSatuFoto(nomorSesi);
                }, 200); 

            } else {
                // Kalau gagal (misal wajah gak ketemu), jangan naikkan counter, tapi coba lagi
                // Kurangi totalFoto karena file gagal disimpan
                totalFoto--; 
                document.getElementById("status").innerText = "Mencari wajah... (Pastikan wajah di kotak)";

                // Coba lagi langsung
                setTimeout(() => {
                    ambilSatuFoto(nomorSesi);
                }, 100);
            }
        })
        .catch(err => {
            console.error(err);
            // Kalau error jaringan, coba lagi
            totalFoto--;
            setTimeout(() => { ambilSatuFoto(nomorSesi); }, 500);
        });
    }

    function updateProgress() {
        // Progress per sesi saja biar enak dilihat (0-100% per sesi)
        let persen = (countSesi / 20) * 100;
        document.getElementById("progressBar").style.width = persen + "%";
        document.getElementById("progressBar").innerText = Math.round(persen) + "%";
    }

    function siapkanSesiBerikutnya(nomorSesi) {
        if (nomorSesi < 4) {
            let nextConfig = sesiList[nomorSesi]; 
            document.getElementById("instruksi").innerText = "ISTIRAHAT SEBENTAR. SIAPKAN POSE BERIKUTNYA.";
            document.getElementById("btn-container").innerHTML = 
                `${nextConfig.btnNext}`;

            // Reset Progress Bar visual
            document.getElementById("progressBar").className = "progress-bar bg-warning";
        } else {
            document.getElementById("instruksi").innerText = "PENGAMBILAN DATA SELESAI!";
            document.getElementById("instruksi").className = "fw-bold text-success mb-3";
            document.getElementById("progressBar").className = "progress-bar bg-success";
            document.getElementById("btn-container").innerHTML = 
                `KEMBALI & TRAINING MODEL`;
        }
    }

